def separate_paren_groups(paren_string: str) -> list[str]:
    result, group = [], []
    depth = 0

    for char in paren_string.replace(' ', ''):
        if char == '(':
            depth += 1
            group.append(char)
        elif char == ')':
            depth -= 1
            group.append(char)
            if depth == 0:
                result.append(''.join(group))
                group.clear()

    return result
```

