from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """Return deepest nesting level for each parenthesis group."""
    def max_depth(s):
        depth = maxd = 0
        for c in s:
            if c == '(':
                depth += 1
                maxd = max(maxd, depth)
            else:
                depth -= 1
        return maxd

    return [max_depth(g) for g in paren_string.split() if g]
```

