def is_palindrome(s: str) -> bool:
    return s == s[::-1]

def make_palindrome(s: str) -> str:
    """Return shortest palindrome starting with s."""
    if not s:
        return ''
    i = 0
    while not is_palindrome(s[i:]):
        i += 1
    return s + s[:i][::-1]
