import math

def poly(xs: list, x: float):
    return sum(coeff * x**i for i, coeff in enumerate(xs))

def find_zero(xs: list):
    begin, end = -1., 1.
    while poly(xs, begin) * poly(xs, end) > 0:
        begin *= 2.0
        end *= 2.0
    while end - begin > 1e-10:
        mid = (begin + end) / 2.0
        if poly(xs, mid) * poly(xs, begin) > 0:
            begin = mid
        else:
            end = mid
    return begin
```

