def fib4(n: int):
    """Return n-th Fib4 number: fib4(0-3)=[0,0,2,0]; for n>3: fib4(n)=sum(last four)."""
    if n < 2:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0  # fib4(0..3)
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d
