def search(lst):
    '''
    Return the greatest positive integer whose frequency in the list is at least its value.
    If none exist, return -1.
    '''
    if not lst:
        return -1
    max_val = max(lst)
    freq = [0] * (max_val + 1)
    for x in lst:
        freq[x] += 1
    ans = -1
    for i in range(1, max_val + 1):
        if freq[i] >= i:
            ans = i
    return ans

def triangle_area(a, b, c):
    '''
    Return area of triangle with sides a, b, c rounded to 2 decimals.
    Return -1 if sides do not form a valid triangle.
    '''
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    return round((s * (s - a) * (s - b) * (s - c)) ** 0.5, 2)

