def numerical_letter_grade(grades):
    """Convert GPAs to letter grades per given thresholds."""
    thresholds = [
        (4.0, "A+"), (3.7, "A"), (3.3, "A-"), (3.0, "B+"),
        (2.7, "B"), (2.3, "B-"), (2.0, "C+"), (1.7, "C"),
        (1.3, "C-"), (1.0, "D+"), (0.7, "D"), (0.0, "D-")
    ]

    result = []
    for gpa in grades:
        if gpa == 4.0:
            result.append("A+")
            continue
        for threshold, grade in thresholds:
            if gpa > threshold:
                result.append(grade)
                break
        else:
            result.append("E")
    return result
```

