    """
    Return the count of integers in arr whose signed digit sum is positive.
    For negative numbers, the first digit is negative (e.g., -123 → -1, 2, 3).
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def signed_digit_sum(n):
        if n < 0:
            digits = [int(d) for d in str(-n)]
            digits[0] *= -1
        else:
            digits = [int(d) for d in str(n)]
        return sum(digits)

    positive_sums = [signed_digit_sum(x) for x in arr if signed_digit_sum(x) > 0]
    return len(positive_sums)

