def get_odd_collatz(n):
    """
    Return sorted odd numbers in the Collatz sequence starting from n.
    """
    odd_nums = [n] if n % 2 else []
    while n > 1:
        n = n // 2 if n % 2 == 0 else n * 3 + 1
        if n % 2:
            odd_nums.append(n)
    return sorted(odd_nums)
