def minPath(grid, k):
    n = len(grid)
    # Find smallest neighbor of cell containing 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                neighbors = []
                if i > 0: neighbors.append(grid[i-1][j])
                if j > 0: neighbors.append(grid[i][j-1])
                if i < n-1: neighbors.append(grid[i+1][j])
                if j < n-1: neighbors.append(grid[i][j+1])
                min_neighbor = min(neighbors)
                break

    # Construct alternating path [1, min_neighbor, 1, min_neighbor, ...]
    return [1 if i % 2 == 0 else min_neighbor for i in range(k)]
```

